source.jsLib:
function decrypt(encryptedTxt, keySeed) {
    const { java } = this;
    let result;
    try {
        const fullKey = java.md5Encode(keySeed);
        const ivBytes = java.strToBytes(fullKey.substring(0, 16));
        const keyBytes = java.strToBytes(fullKey.substring(16));

        const Cipher = java.createSymmetricCrypto(
            "AES/CBC/Pkcs7Padding",
            keyBytes,
            ivBytes
        );

        result = Cipher.decryptStr(java.base64DecodeToByteArray(encryptedTxt));
    } catch (e) {
        java.log(e.message);
        result = "解密失败";
    }
    return result;
}

ruleToc.chapterList:
ol > li
<js>
let Regex_ = /(data-[a-zA-Z0-9]+)/g;
let label = result.select('li')[0].outerHtml().match(Regex_)[1];
result.sort((a, b) => +a.attr(label) - +b.attr(label));
let chapterList = result.select('a').toArray().map(e => {
    let labeln = e.outerHtml().match(Regex_);
    return {
        title: String(e.attr(labeln[0])).trim() || e.text(),
        url: java.base64Decode(e.attr(labeln[1]))
    }
});
JSON.stringify(chapterList);
</js>
$[*]

