source.loginUrl:
openBrowser = () => {
    java.startBrowser('https://m.libahao2.com', '若页面出现验证，请手动通过，然后返回阅读即可');
}

checkCookie = () => {
    var c = java.getCookie('https://m.libahao2.com');
    java.toast('Cookie: ' + (c ? c : '当前为空'));
}

clearCookie = () => {
    java.clearCookie('https://m.libahao2.com');
    java.toast('🗑️ Cookie 已清除');
}
login = () => {};

ruleContent.content:
@js:var doc = org.jsoup.Jsoup.parse(result);
var content = String(doc.select('#chapterContent').html());
content = content.replace(/<b style="color:#ff0000[^"]*"[^>]*>[^<]*<\/b>/g, '');
content = content.replace(/<a [^>]*rel="next"[^>]*>[\s\S]*?<\/a>/g, '');
content;

