ruleContent.nextContentUrl:
@js:var doc = org.jsoup.Jsoup.parse(result);
var nextUrl = '';
var footerLinks = doc.select('.footer-nav a');
if (footerLinks.size() >= 3) {
    var lastLink = footerLinks.get(footerLinks.size() - 1);
    if (lastLink.text().indexOf('下一页') >= 0) {
        nextUrl = lastLink.attr('href');
    }
}
nextUrl;

ruleToc.chapterList:
@js:var doc = org.jsoup.Jsoup.parse(result);
var chapters = [];
var uls = doc.select('div.chapter-list ul');
for (var i = 0; i < uls.size(); i++) {
    var ul = uls.get(i);
    var parent = ul.parent();
    if (parent != null && parent.hasClass('tab-content')) continue;
    var links = ul.select('li a');
    for (var j = 0; j < links.size(); j++) {
        chapters.push([links.get(j).text(), links.get(j).attr('href')]);
    }
}
chapters;

